namespace docking.action;





using org.apache.logging.log4j;
using org.apache.logging.log4j;

using docking;
using docking;
using generic.util.action;

public class ShowFocusCycleAction : DockingAction {
	static readonly Logger log = LogManager.getLogger(typeof(ShowFocusCycleAction));

	public ShowFocusCycleAction() : base("Show Focus Cycle", DockingWindowManager.DOCKING_WINDOWS_OWNER)
    {
		createSystemKeyBinding(SystemKeyBindings.FOCUS_CYCLE_INFO_KEY);
		setEnabled(true);

		// System action; no help needed
		DockingWindowManager.getHelpService().excludeFromHelp(this);
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		log.trace("====================================");

		KeyboardFocusManager kfm = KeyboardFocusManager.getCurrentKeyboardFocusManager();
		Component focusOwner = kfm.getFocusOwner();
		if (focusOwner != null) {
			Container focusRoot = focusOwner.getFocusCycleRootAncestor();
			FocusTraversalPolicy policy = focusRoot.getFocusTraversalPolicy();
			log.trace("FocusCycleRoot: " + focusRoot);
			log.trace("FocusTraversalPolicy: " + policy.GetType().getName() + ": " +
				System.identityHashCode(policy));
			Component nextComponent = policy.getFirstComponent(focusRoot);
			Component firstComponent = nextComponent;
			log.trace("\tfirst component: " + printComp(nextComponent));
			while ((nextComponent =
				policy.getComponentAfter(focusRoot, nextComponent)) != firstComponent) {
				log.trace("\tcomponent: " + printComp(nextComponent));
			}
		}
		else {
			log.trace("No focus Owner");
		}

		log.trace("");
	}

	private string printComp(Component comp) {
		if (comp == null) {
			return null;
		}

		if (comp is JFrame) {
			JFrame frame = (JFrame) comp;
			return "Window (" + frame.getTitle() + "): " + System.identityHashCode(frame);
		}

		return comp.GetType().getName() + ": " + System.identityHashCode(comp);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return true;
	}

}
